<template>
	<d2-container v-if="isDev">

		<div  style="margin-bottom: 20px;">
			<el-button type="primary" size="medium" @click="refresh">刷新</el-button>
			<el-button type="success" size="medium" @click="showDialog('新建同级')">新建同级</el-button>
			<el-button type="success" size="medium" @click="showDialog('新建下级')">新建下级</el-button>
			<el-button type="warning" size="medium" @click="showDialog('编辑节点')">编辑节点</el-button>
			<el-button type="danger" size="medium" @click="DeleteTreeNode()">删除</el-button>
		</div>
		<el-card :style="{height:cardHeight+'px'}" shadow="never">
			<el-tree :data="treedata" ref="MenuTree" node-key="MenuKey" highlight-current :props="defaultProps"></el-tree>
		</el-card>

		<el-dialog :title="addType" :visible.sync="dialogVisible">
			<el-form :model="form" label-width="120px">
				<el-form-item label="标题title">
					<el-input v-model="form.title" clearable placeholder="例如商品档案"></el-input>
				</el-form-item>
				<el-form-item label="图标icon">
					<el-input v-model="form.icon" clearable placeholder="请从fontawesome网站拷贝"></el-input>
				</el-form-item>
				<el-form-item label="路径path">
					<el-input v-model="form.path" clearable placeholder="例如/ItemInfo  (父节点不需要)"></el-input>
				</el-form-item>
				<el-form-item label="权限AuthKey">
					<el-input-number v-model="form.AuthKey" :min="1"></el-input-number>
				</el-form-item>
				<el-form-item v-if="showSort" label="排序">
					<el-input-number style="margin-right: 10px;" v-model="form.MenuSort" :min="10" :step="10"></el-input-number>
					(权重越大越靠后)
				</el-form-item>
			</el-form>
			<div slot="footer" class="dialog-footer">
				<el-button @click="handleCancel">取 消</el-button>
				<el-button type="primary" @click="handleSave">确 定</el-button>
			</div>
		</el-dialog>

	</d2-container>
</template>

<script>
	import {
		GetMenuTree,
		AddMenu,
		UpdateMenuByID,
		DeleteMenu,
		GetMenuByID
	} from '@api/MenuInfo.js'
	import {
		Query,
		Aud
	} from '@api/shuju.js'
	export default {
		name: 'MenuInfo',
		data() {
			return {
				isDev:false,
				cardHeight: 100,
				//目录树
				treedata: [],
				defaultProps: {
					children: 'children',
					label: 'label'
				},

				dialogVisible: false,
				addType: '',
				showSort:false,
				MenuKey: 0,
				form: {
					title: '',
					icon: '',
					path: '',
					MenuSort: 0,
					AuthKey: 0
				}

			}
		},
		mounted() {
			this.checkDev()
			this.autoCardHeight()
			this.InitMenuTree()
		},
		methods: {
			checkDev(){
				this.isDev=(process.env.NODE_ENV === 'development')?true:false
			},
			//卡片根据浏览器调整高度---
			autoCardHeight() {
				this.cardHeight = window.innerHeight - 200;
				window.onresize = () => {
					return (() => {
						this.cardHeight = window.innerHeight - 200;
					})();
				};
			},
			InitMenuTree() {
				Query({
					tablename:'菜单',
			        field:'id',
			        tj:true  //加载条件
				})
					.then(res => {
						const tree = res.data;
                       let str = '';
                        let tree1 = tree.filter(function(item,index){    //获取不重单
                        if(item.一级菜单 != str){
                         str = item.一级菜单;
                                    return item
			                        }
			                        })
									//console.log(menu1)
									 let tree2 = [];
                                tree1.forEach(function(item,index){     //对一级菜单进行遍历
                                  let obj2 = {
	                              label:item.一级菜单,
								  id:item.id
	                              //path:item.path,
	                              //icon: item.icon
		                           };
	                              let arr2 = [];
	                              tree.forEach(function(v,i){        //再对其所属的二级菜单进行遍历
	                            if(v.一级菜单 == item.一级菜单 ){
	                                   if(v.二级菜单 !=''){
	                                   arr2.push({
									   label:v.二级菜单,
									   id:v.二级菜单						
									   //path:v.path
	                                })
		                        }

		                    }
		                    })
		                    obj2.children = arr2;
	                        tree2.push(obj2)
                            })
							console.log(tree2)	
						this.treedata = tree2
						//this.treedata = res.TreeData
					}).catch(err => {})
			},

			refresh(){
				this.InitMenuTree()
				this.$message.success('刷新成功')
			},

			showDialog(e) {
				//e有新建同级、新建下级、编辑节点
				let key = this.$refs.MenuTree.getCurrentKey()
				this.addType = e
				if (key !== null) {
					if (this.addType === '编辑节点') {
						this.showSort=true
						GetMenuByID({
								MenuKey: key
							})
							.then(res => {
								this.MenuKey = key
								this.form = res
								this.dialogVisible = true
							}).catch(err => {})
					} else {
						this.showSort=false
						let obj = this.form
						for (let key in obj) {							
							obj[key] = null
						}
						this.dialogVisible = true
					}
				} else {
					this.$message({
						showClose: true,
						message: '请先选择节点',
						type: 'error'
					});
				}
			},
			handleCancel() {
				this.addType = ''
				this.dialogVisible = false
			},

			handleSave() {
				let key = this.$refs.MenuTree.getCurrentKey()
				if (key !== null) {
					if (this.addType === '新建同级' || this.addType === '新建下级') {						
						AddMenu({
								form: this.form,
								MenuKey: key,
								addType: this.addType
							})
							.then(res => {
								if (this.addType === '新建同级') { //增加同级
									this.$refs.MenuTree.insertAfter(res.data, key)
								} else { //增加下级
									this.$refs.MenuTree.append(res.data, key)
								}
								this.$refs.MenuTree.setCurrentKey(res.data.MenuKey)
								this.dialogVisible=false
								this.$message.success(this.addType + '节点成功')

							})
							.catch(err => {})
					} else { //编辑保存
						UpdateMenuByID({
								form: this.form,
								MenuKey: this.MenuKey,
							})
							.then(res => {
								let data = this.$refs.MenuTree.getCurrentNode()
								data.label = this.form.title
								this.dialogVisible=false
								this.$message.success('重命名成功')
								
							})
							.catch(err => {})
					}

				} else {
					this.$message({
						showClose: true,
						message: '请先选择节点',
						type: 'error'
					});
				}
			},
			// RenameTreeNode() {
			// 	let key = this.$refs.MenuTree.getCurrentKey()
			// 	if (key !== null) {
			// 		this.$prompt('请输入节点新名称', '提示', {
			// 			confirmButtonText: '确定',
			// 			cancelButtonText: '取消',
			// 		}).then(({
			// 			value
			// 		}) => {
			// 			UpdateMenu({
			// 					title: value,
			// 					MenuKey: key,
			// 				})
			// 				.then(res => {
			// 					let data = this.$refs.MenuTree.getCurrentNode()
			// 					data.label = value
			// 					this.$message.success('重命名成功')
			// 				})
			// 				.catch(err => {})

			// 		}).catch(() => {});
			// 	} else {
			// 		this.$message.error('请先选择节点')
			// 	}
			// },


			DeleteTreeNode() {
				let key = this.$refs.MenuTree.getCurrentKey()
				if (key !== null) {
					let data = this.$refs.MenuTree.getCurrentNode()
					if (!data.children || data.children.length == 0) {
						this.$confirm('确定要删除该节点?', '提示', {
							confirmButtonText: '确定',
							cancelButtonText: '取消',
							type: 'warning'
						}).then(() => {
							DeleteMenu({
									MenuKey: key,
								})
								.then(res => {
									this.$refs.MenuTree.remove(key)
									this.$message.success('删除成功！')
								})
								.catch(err => {})
						}).catch(() => {});
					} else {
						this.$message.warning('该节点仍在子节点，不允许删除！');
					}
				} else {
					this.$message.warning('请先选择节点')
				}
			}
		}

	}
</script>

